'use strict';
// Lógica de programação (Python), parte A: unidades 2 (lições novas), 4 e 5.
(()=>{
  let serial=0;
  const q=(prompt,correct,wrong,explanation,code)=>{const options=[correct,...wrong];const answer=serial++%options.length;for(let i=0;i<answer;i++)options.unshift(options.pop());return {type:'choice',prompt,options,answer,explanation,code};};
  const t=(prompt,accepted,explanation,code)=>({type:'text',prompt,accepted:Array.isArray(accepted)?accepted:[accepted],explanation,code});
  const g=(prompt,accepted,explanation,code)=>({...t(prompt,accepted,explanation,code),type:'gap'});
  const o=(prompt,steps,explanation)=>({type:'order',prompt,options:[...steps].reverse(),answer:steps.map((_,i)=>steps.length-i-1),explanation});
  const p=(prompt,pairs,explanation)=>({type:'pairs',prompt,pairs,explanation});
  window.PYTHON_LOGIC_UNITS=window.PYTHON_LOGIC_UNITS||{};

  window.PYTHON_LOGIC_UNITS[2]=[
  {id:'py-lg-2-4-ler-saidas',title:'Leia fluxos com várias saídas',subtitle:'Aplicação · rastreamento de caminhos',theory:'Um fluxo de boletim recebe uma nota inteira de 0 a 10. O primeiro losango pergunta nota ≥ 7: se for verdadeiro, mostra Aprovado. Se for falso, um segundo losango pergunta nota ≥ 5: verdadeiro leva a Recuperação, falso leva a Reprovado. Para ler um fluxo com três saídas, rastreie à mão: anote a entrada, responda cada losango na ordem em que ele aparece e siga somente a seta escolhida. Cada execução termina em exatamente uma saída, e entradas fora de 0 a 10 não têm caminho definido.',questions:[
  q('Com nota = 7, qual saída o fluxo apresenta?','Aprovado',['Recuperação','Reprovado'],'7 ≥ 7 é verdadeiro já no primeiro losango. A seta Sim leva a Aprovado e o segundo losango nem é consultado.'),
  q('Com nota = 5, qual saída o fluxo apresenta?','Recuperação',['Aprovado','Reprovado'],'5 ≥ 7 é falso, então seguimos a seta Não. No segundo losango, 5 ≥ 5 é verdadeiro: a igualdade conta e o resultado é Recuperação.'),
  t('Com nota = 4, quantos losangos o rastreamento avalia até chegar à saída?',['2','dois'],'4 ≥ 7 é falso e 4 ≥ 5 também é falso. Foram dois losangos, e o segundo Não leva a Reprovado.'),
  p('Associe cada nota ao resultado do rastreamento.',[['nota = 10','Aprovado'],['nota = 6','Recuperação'],['nota = 0','Reprovado'],['nota = 12','Fora do domínio: o fluxo não prevê']],'10 ≥ 7 aprova; 6 falha em ≥ 7 e passa em ≥ 5; 0 falha nos dois testes. A nota 12 viola a entrada permitida, e um bom fluxo precisa de validação antes.'),
  o('Ordene o rastreamento do fluxo para nota = 6.',['Ler nota = 6','Testar nota ≥ 7: falso, seguir a seta Não','Testar nota ≥ 5: verdadeiro, seguir a seta Sim','Mostrar Recuperação','Fim'],'Cada losango só é consultado depois que a seta anterior leva até ele. A saída aparece depois das decisões e o fim vem por último.'),
  q('Quantas setas saem de cada losango deste fluxo?','Duas: uma para Sim e outra para Não',['Três: uma para cada saída final','Uma: a decisão apenas continua o fluxo'],'Cada condição tem resposta verdadeira ou falsa. Três saídas finais surgem de dois losangos encadeados, não de um losango com três setas.'),
  t('Quantas notas inteiras de 0 a 10 levam à saída Recuperação?',['2','dois'],'Só as notas 5 e 6 passam em nota ≥ 5 e falham em nota ≥ 7.'),
  q('Qual conjunto de notas inteiras chega à saída Reprovado?','De 0 a 4',['De 0 a 5','De 5 a 6'],'Reprovado exige falhar em nota ≥ 7 e em nota ≥ 5, ou seja, nota < 5. Com inteiros, isso é 0, 1, 2, 3 e 4.')
  ]},
  {id:'py-lg-2-5-corrigir-defeitos',title:'Corrija o fluxo defeituoso',subtitle:'Revisão · achar e reparar defeitos',theory:'Uma loja dá 10% de desconto quando a compra é de pelo menos 100 reais; abaixo disso, o cliente paga o valor cheio. A compra é um valor não negativo. Um fluxo pode estar errado de formas diferentes: um losango sem a seta Não, uma saída antes da leitura, um limite escrito com o símbolo errado ou duas setas que levam ao mesmo cálculo. Para consertar, reproduza o defeito com uma entrada, localize o bloco onde o caminho se afasta da regra, corrija e teste os dois lados do limite.',questions:[
  q('O losango compra ≥ 100 tem a seta Sim, mas nenhuma seta Não. O que acontece com compra = 50?','O fluxo fica sem destino, porque falta o ramo Não',['O desconto é aplicado mesmo assim','O fluxo mostra o valor cheio automaticamente'],'Toda decisão precisa de caminho para cada resposta. Sem a seta Não, a execução trava no losango.'),
  t('O bloco Mostrar total estava antes de Ler compra. Depois de consertar a ordem, qual total aparece para compra = 200?','180','200 ≥ 100 é verdadeiro, então o total é 200 × 0,9 = 180.'),
  o('Ordene a investigação do defeito do ramo Não ausente.',['Reproduzir o defeito com compra = 99','Marcar o losango onde a execução para','Desenhar a seta Não até o cálculo do valor cheio','Refazer os testes com compra = 99 e compra = 100'],'O defeito é reproduzido antes de ser localizado e a correção só vale depois de ser testada nos dois lados do limite.'),
  p('Associe cada defeito à correção adequada.',[['Losango sem a seta Não','Desenhar o ramo Não'],['Saída antes da leitura','Mover Ler compra para antes do cálculo'],['Seta de retorno sem atualização','Incluir um bloco que atualiza o contador'],['Variável usada sem valor inicial','Inicializar a variável antes do uso']],'Cada correção ataca a causa do defeito: caminho ausente, ordem trocada, repetição sem avanço ou valor indefinido.'),
  t('Um fluxo defeituoso usa compra > 100 no losango. Que total ele calcula para compra = 100?','100','100 > 100 é falso, então o fluxo segue o ramo Não e cobra o valor cheio, embora a regra peça desconto a partir de 100.'),
  q('As setas Sim e Não do losango levam ao mesmo bloco, total = compra × 0,9. Qual é o problema?','A decisão não muda o resultado e quem compra 50 recebe desconto indevido',['O fluxo está correto, pois o desconto sempre é bom','O fluxo nunca termina'],'Um losango só tem sentido se os ramos diferirem. Aqui o ramo Não deveria usar total = compra.'),
  q('Qual par de testes verifica os dois lados do limite da regra?','compra = 99 e compra = 100',['compra = 150 e compra = 200','compra = 100 e compra = 100'],'99 fica logo abaixo e 100 é o próprio limite. Os outros pares testam apenas um lado ou repetem o mesmo caso.'),
  g('Complete o operador para que compras de 100 reais ou mais recebam o desconto.',['>=','≥'],'A regra diz a partir de 100, então a igualdade deve estar incluída: compra >= 100.','if compra ____ 100:\n    total = compra * 0.9\nelse:\n    total = compra')
  ]}
  ];

  window.PYTHON_LOGIC_UNITS[4]=[
  {id:'py-lg-4-1-nome-valor-tipo',title:'Nome, valor e tipo',subtitle:'Apresentação · variáveis e tipos básicos',theory:'Um programa de loja guarda a quantidade de canetas, o preço unitário e o nome do produto. Cada informação vira uma variável: um nome ligado a um valor. O sinal = não compara, ele atribui: o valor à direita é guardado no nome à esquerda. Os valores têm tipo: int para inteiros como 3, float para decimais como 12.5, str para texto entre aspas e bool para True ou False. Um nome começa com letra ou _, não tem espaços e diferencia maiúsculas de minúsculas. Aqui, quantidade é um inteiro não negativo e o preço não é negativo.',questions:[
  q('Em quantidade = 3, qual é o tipo do valor guardado?','int, um número inteiro',['float, um número decimal','str, um texto'],'3 não tem parte decimal nem aspas, portanto é um inteiro.','quantidade = 3'),
  p('Associe cada valor ao seu tipo em Python.',[['3','int'],['12.5','float'],['"3"','str'],['True','bool']],'O ponto decimal indica float, as aspas indicam texto, e True é um valor lógico. Por isso "3" e 3 são tipos diferentes.'),
  q('Qual destes é um nome válido de variável?','preco_unit',['2preco','preco unit','preco-unit'],'Nomes não podem começar com dígito, ter espaço ou hífen. O sublinhado é permitido.'),
  t('Qual valor fica guardado em total?',['37.5','37,5'],'3 × 12.5 = 37.5. O resultado de int com float é float.','quantidade = 3\npreco = 12.5\ntotal = quantidade * preco'),
  q('Como se lê corretamente a linha x = 5?','Guarde o valor 5 no nome x',['Pergunte se x é igual a 5','Declare que x e 5 nunca poderão mudar'],'O = faz atribuição. A comparação usa ==, e o valor de x pode ser trocado depois.','x = 5'),
  o('Ordene as linhas para calcular e exibir o total com frete de 5.',['quantidade = 3','subtotal = quantidade * 12.5','total = subtotal + 5','print(total)'],'Cada linha usa um nome criado antes dela. Usar subtotal antes de atribuí-lo causaria NameError.'),
  q('Só existe a variável preco. O que acontece ao executar print(Preco)?','Dá erro NameError, porque Preco é outro nome',['Mostra o valor de preco normalmente','Mostra a palavra Preco'],'Python diferencia maiúsculas de minúsculas, então Preco e preco são nomes distintos.','preco = 12.5\nprint(Preco)'),
  g('Complete a quantidade para que total seja 25.0.','2','12.5 × 2 = 25.0, então a quantidade precisa ser 2.','preco = 12.5\nquantidade = ____\ntotal = preco * quantidade')
  ]},
  {id:'py-lg-4-2-rastrear-atribuicoes',title:'Rastreie atribuições',subtitle:'Prática guiada · tabela de valores',theory:'Uma conta bancária começa com saldo = 100, um inteiro não negativo, e recebe saques e depósitos. Para saber o valor final, monte uma tabela de rastreio: uma linha por instrução e uma coluna por variável. Em saldo = saldo - 30, o computador calcula o lado direito com o valor antigo (100 - 30) e só então grava 70 em saldo. Copiar uma variável guarda o valor do momento; mudar a original depois não altera a cópia. Trocar dois valores exige uma variável auxiliar.',questions:[
  t('Qual é o valor final de saldo?','80','Rastreio: 100, depois 100 − 30 = 70, depois 70 + 10 = 80.','saldo = 100\nsaldo = saldo - 30\nsaldo = saldo + 10'),
  q('Qual é o valor de b ao final?','4',['9','13'],'b recebe uma cópia do valor 4 que a tinha naquele momento. Mudar a depois para 9 não altera b.','a = 4\nb = a\na = 9'),
  t('Qual é o valor final de y?','15','x = 2 e y = 3. Depois x = 2 + 3 = 5. Por fim y = 5 × 3 = 15, usando o novo x.','x = 2\ny = 3\nx = x + y\ny = x * y'),
  o('Ordene as linhas que trocam os valores de a e b.',['aux = a','a = b','b = aux'],'aux guarda o valor original de a antes de a ser sobrescrita. Depois b recebe esse valor guardado.'),
  q('Com a = 1 e b = 2, o que ocorre ao executar a = b e depois b = a?','a e b ficam ambos com 2',['a vira 2 e b vira 1','a e b ficam ambos com 1'],'a = b apaga o 1 original de a. Depois b = a copia o 2. Sem variável auxiliar, o valor se perde.'),
  p('Com contador = 5 antes de cada instrução, associe a instrução ao novo valor.',[['contador = contador + 1','6'],['contador = contador - 2','3'],['contador = contador * 2','10'],['contador = 0','0']],'5 + 1 = 6, 5 − 2 = 3 e 5 × 2 = 10. A última instrução ignora o valor antigo.'),
  q('Por que saldo = saldo - 30 não é uma equação impossível?','O lado direito usa o valor antigo, e o resultado vira o novo valor de saldo',['Porque 30 é igual a zero','Porque Python ignora o sinal de menos'],'Atribuição não é igualdade matemática. Primeiro se calcula, depois se grava.'),
  g('Complete o operador para que saldo passe de 100 para 75.','-','100 − 25 = 75. O operador de subtração é -.','saldo = 100\nsaldo = saldo ____ 25\n# saldo agora vale 75')
  ]},
  {id:'py-lg-4-3-expressoes-precedencia',title:'Expressões e precedência',subtitle:'Aprofundamento · operadores aritméticos',theory:'Dezessete balas serão repartidas entre 5 crianças, ambos inteiros e o número de crianças maior que zero. A divisão inteira // diz quantas balas cada criança recebe, e o resto % diz quantas sobram. Além de + e -, Python tem * para multiplicar, / para divisão com resultado decimal e ** para potência. A ordem é: parênteses, depois **, depois *, /, // e %, e por fim + e -. Dividir por zero provoca erro.',questions:[
  t('Quanto vale 17 // 5?','3','5 cabe 3 vezes em 17, pois 3 × 5 = 15.','17 // 5'),
  t('Quanto vale 17 % 5?','2','Depois de distribuir 15 balas, restam 17 − 15 = 2.','17 % 5'),
  q('Qual é o valor de 2 + 3 * 4?','14',['20','9'],'A multiplicação vem antes: 3 × 4 = 12 e depois 2 + 12 = 14.','2 + 3 * 4'),
  t('Quanto vale (2 + 3) * 4?','20','Os parênteses mudam a ordem: 2 + 3 = 5 e 5 × 4 = 20.','(2 + 3) * 4'),
  o('Ordene a avaliação de 3 + 2 * 4 ** 2.',['4 ** 2 resulta em 16','2 * 16 resulta em 32','3 + 32 resulta em 35'],'A potência tem maior precedência, depois vem a multiplicação e por último a soma.'),
  q('Qual é o resultado de 7 / 2 em Python?','3.5',['3','4'],'A barra simples sempre dá um float. Para o quociente inteiro 3 usaríamos 7 // 2.','7 / 2'),
  p('Associe cada expressão ao seu valor.',[['10 % 3','1'],['10 // 3','3'],['10 / 4','2.5'],['10 - 2 * 3','4']],'10 = 3 × 3 + 1; 10 / 4 = 2.5; e 10 − 6 = 4 porque a multiplicação precede a subtração.'),
  g('Complete o operador para guardar em sobra as balas que não puderam ser repartidas.','%','O resto da divisão é obtido com %. Para 17 e 5, sobra recebe 2.','balas = 17\ncriancas = 5\nsobra = balas ____ criancas')
  ]},
  {id:'py-lg-4-4-entrada-conversao',title:'Entrada, conversão e média',subtitle:'Aplicação · input, int e médias',theory:'Um cronômetro recebe uma duração em minutos, inteira e não negativa, e precisa mostrar horas e minutos. Para 135 minutos, 135 // 60 dá 2 horas e 135 % 60 dá 15 minutos. A função input() sempre devolve texto, então int(texto) deve converter a entrada antes de qualquer conta. Se o texto não for numérico, int() falha com ValueError. Na média de duas notas, parênteses são obrigatórios: (n1 + n2) / 2 é diferente de n1 + n2 / 2.',questions:[
  q('O usuário digita 7. O que o código mostra?','77',['14','Um erro de tipos'],'input() devolve o texto "7". Somar dois textos concatena, resultando em "77".','n = input()\nprint(n + n)'),
  t('Com minutos = 135, quanto vale minutos // 60?','2','60 cabe duas vezes em 135, pois 2 × 60 = 120.','minutos = 135\nhoras = minutos // 60'),
  t('Com minutos = 135, quanto vale minutos % 60?','15','Depois de 120 minutos, restam 135 − 120 = 15.','minutos = 135\nresto = minutos % 60'),
  t('Com minutos = 45, quanto vale minutos // 60?','0','45 é menor que 60, então não completa nenhuma hora. O resto é 45.','minutos = 45\nhoras = minutos // 60'),
  o('Ordene as linhas que leem os minutos e calculam as horas.',['texto = input()','minutos = int(texto)','horas = minutos // 60','print(horas)'],'A leitura vem primeiro, a conversão antes de qualquer conta e a exibição por último.'),
  q('Com n1 = 6 e n2 = 8, qual valor guarda media = n1 + n2 / 2?','10.0',['7.0','14.0'],'A divisão vem antes: 8 / 2 = 4.0, e 6 + 4.0 = 10.0. A média correta exigiria parênteses.','media = n1 + n2 / 2'),
  p('Associe cada expressão ao resultado.',[['int("42")','Inteiro 42'],['float("2.5")','Decimal 2.5'],['"4" + "2"','Texto "42"'],['int("7") + 1','Inteiro 8']],'int e float convertem texto em número. Somar textos junta caracteres, e somar após converter faz conta.'),
  g('Complete o operador para que media seja 7.0.','/','(6 + 8) / 2 = 14 / 2 = 7.0. A divisão de média é /.','n1 = 6\nn2 = 8\nmedia = (n1 + n2) ____ 2')
  ]},
  {id:'py-lg-4-5-revisao-expressoes',title:'Rastreie e corrija',subtitle:'Desafio de revisão · variáveis e expressões',theory:'Neste desafio, você age como o computador: anote o valor de cada variável linha a linha, calcule cada expressão com a ordem correta e compare com o resultado esperado. Os problemas misturam compras, troco, notas e tempo, sempre com entradas válidas. Um erro de execução, como NameError ou TypeError, aponta uma linha concreta. Já um erro de lógica roda sem avisos e produz um valor errado, por isso só os testes com valores conhecidos o revelam.',questions:[
  q('Qual valor de total aparece na tela?','10',['15','5'],'A linha total + 5 calcula 15, mas não atribui o resultado a nenhuma variável. total continua 10.','total = 10\ntotal + 5\nprint(total)'),
  t('Qual valor de b aparece na tela?','6','b = 3 × 2 = 6 no momento da atribuição. Mudar a para 10 depois não recalcula b.','a = 3\nb = a * 2\na = 10\nprint(b)'),
  q('Um cliente paga 50 por uma compra de 37. Qual valor o código produz para troco?','-13',['13','87'],'37 − 50 = −13. A subtração está na ordem errada e o troco sai negativo.','pago = 50\npreco = 37\ntroco = preco - pago'),
  t('Qual é o valor correto de troco com pago = 50 e preco = 37?','13','A expressão correta é pago − preco: 50 − 37 = 13.'),
  p('Associe cada trecho ao erro que ele causa.',[['print(totl) quando só existe total','NameError: nome inexistente'],['"5" + 3','TypeError: texto somado a número'],['10 / 0','ZeroDivisionError: divisor zero'],['int("abc")','ValueError: texto não numérico']],'Cada erro nomeia o problema: nome desconhecido, tipos incompatíveis, divisão por zero e conversão impossível.'),
  o('Ordene a correção de uma saída errada.',['Executar um caso pequeno e anotar a saída esperada','Rastrear as variáveis linha a linha','Achar a primeira linha em que o valor diverge','Corrigir a expressão dessa linha','Reexecutar o caso e testar um valor de limite'],'A primeira divergência indica a causa. A correção só é confiável quando se repetem os testes, inclusive nos limites.'),
  q('Para nota1 = 8 e nota2 = 10, a média correta é 9.0. Qual correção de media = nota1 + nota2 / 2 chega a esse valor?','media = (nota1 + nota2) / 2',['media = nota1 + (nota2 / 2)','media = nota1 + nota2 // 2'],'(8 + 10) / 2 = 9.0. As outras duas opções calculam 8 + 5 = 13.'),
  g('Complete o operador para obter somente as horas inteiras em 3725 segundos.','//','3725 // 3600 = 1, porque 3600 cabe uma vez em 3725. A divisão decimal daria 1.034...','segundos = 3725\nhoras = segundos ____ 3600')
  ]}
  ];

  window.PYTHON_LOGIC_UNITS[5]=[
  {id:'py-lg-5-1-and-or-not',title:'Combine condições com and, or e not',subtitle:'Apresentação · operadores lógicos',theory:'Um cinema só deixa entrar quem tem ingresso e tem pelo menos 14 anos. A idade é inteira, de 0 a 120, e tem_ingresso vale True ou False. O operador and exige que as duas condições sejam verdadeiras. O operador or basta que uma seja verdadeira. O operador not inverte o valor lógico. Para duas condições existem quatro combinações possíveis e montar a tabela delas evita erros de raciocínio.',questions:[
  q('Com tem_ingresso = True e idade = 12, qual é o resultado da condição?','False',['True','Erro de sintaxe'],'12 >= 14 é falso. Com and, uma parte falsa torna o resultado falso.','tem_ingresso and idade >= 14'),
  q('Com pago = False e cortesia = True, qual é o resultado de pago or cortesia?','True',['False','Erro de sintaxe'],'Com or, basta uma parte verdadeira. A cortesia já libera a entrada.','pago or cortesia'),
  p('Associe cada elemento ao seu significado.',[['and','Verdadeiro só se os dois lados forem verdadeiros'],['or','Falso só se os dois lados forem falsos'],['not','Inverte o valor lógico'],['>=','Compara e resulta em True ou False']],'and exige tudo e or aceita qualquer um. not troca True por False e vice-versa. Já >= é uma comparação.'),
  t('Entre as 4 combinações de valores de a e b, quantas tornam (a and b) verdadeiro?','1','Só a combinação True e True satisfaz and.'),
  t('Entre as 4 combinações de valores de a e b, quantas tornam (a or b) verdadeiro?','3','Só False e False falha. As outras três combinações têm pelo menos um True.'),
  q('Com tem_ingresso = True e idade = 14, qual é o resultado?','True',['False','Depende da hora'],'14 >= 14 é verdadeiro, então o limite entra. As duas partes são verdadeiras.','tem_ingresso and idade >= 14'),
  o('Ordene a avaliação de not (idade < 14) and tem_ingresso com idade = 10 e tem_ingresso = True.',['Comparar: 10 < 14 resulta em True','Aplicar not: not True resulta em False','Combinar: False and True resulta em False'],'Primeiro se resolve a comparação dentro dos parênteses, depois o not e por último o and.'),
  g('Complete o operador para que entre somente quem atende às duas exigências.','and','Como a pessoa precisa ter ingresso e idade mínima, o operador é and.','if tem_ingresso ____ idade >= 14:\n    print("Pode entrar")')
  ]},
  {id:'py-lg-5-2-faixas-limites',title:'Faixas e limites',subtitle:'Prática guiada · intervalos de valores',theory:'Um parque cobra por faixa etária: criança de 0 a 11 anos, adulto de 12 a 59 e idoso a partir de 60. A idade é inteira e não negativa. Uma faixa fechada é escrita como 12 <= idade <= 59, que equivale a idade >= 12 and idade <= 59. Trocar and por or cria uma condição verdadeira para quase qualquer idade. Para testar uma faixa, sempre use os valores do limite e os vizinhos: 11, 12, 59 e 60.',questions:[
  q('Com idade = 12, qual é o resultado de 12 <= idade <= 59?','True',['False','Erro de sintaxe'],'12 <= 12 é verdadeiro e 12 <= 59 também. O limite inferior pertence à faixa.','12 <= idade <= 59'),
  p('Associe cada idade à classificação do parque.',[['idade 11','Criança'],['idade 12','Adulto'],['idade 60','Idoso'],['idade -3','Entrada inválida']],'11 é o último valor da faixa infantil, 12 inicia a faixa adulta e 60 inicia a de idoso. Idade negativa viola o domínio.'),
  t('Qual é a maior idade inteira que ainda é classificada como adulto?','59','A faixa adulta vai de 12 a 59, e 60 já é idoso.'),
  q('Com idade = 5, qual é o resultado de idade >= 12 or idade <= 59?','True, porque 5 <= 59 já basta com or',['False, porque 5 não é maior ou igual a 12','Erro de sintaxe'],'Com or, uma parte verdadeira basta. A condição vale para quase todas as idades e não define uma faixa. O correto seria and.','idade >= 12 or idade <= 59'),
  t('Quantas idades inteiras de 0 a 120 pertencem à faixa 12 <= idade <= 59?','48','De 12 a 59 há 59 − 12 + 1 = 48 valores. A soma de 1 conta os dois extremos.'),
  o('Ordene o raciocínio que classifica idade = 60 pelo código: inválida, criança, adulto, idoso.',['Verificar idade < 0: falso','Verificar idade < 12: falso','Verificar idade <= 59: falso','Cair no else e classificar como idoso'],'Cada teste falso empurra o fluxo ao teste seguinte. Se todos falham, o else assume os valores restantes.'),
  q('Qual condição descreve corretamente a faixa adulta de 12 a 59?','12 <= idade <= 59',['idade >= 12 or idade <= 59','12 < idade < 59'],'A última opção exclui 12 e 59, que pertencem à faixa. A segunda aceita quase tudo.'),
  g('Complete a comparação para incluir a idade 59 na faixa adulta.','<=','Com idade <= 59, o valor 59 ainda satisfaz a condição. Com < ele ficaria de fora.','if 12 <= idade ____ 59:\n    print("Adulto")')
  ]},
  {id:'py-lg-5-3-ordem-dos-testes',title:'A ordem dos testes importa',subtitle:'Aprofundamento · if, elif e else em cadeia',theory:'Uma loja devolve cashback conforme o valor da compra, que é sempre maior ou igual a zero: 15% a partir de 500, 10% a partir de 200, 5% a partir de 100 e nada abaixo disso. Em uma cadeia if, elif e else, os testes rodam de cima para baixo e somente o bloco da primeira condição verdadeira é executado. Por isso as faixas mais restritivas devem vir primeiro. Se o teste compra >= 100 vier no topo, uma compra de 600 já cai nele e nunca chega aos 15%.',questions:[
  t('Qual é a taxa para compra = 200?','10','200 >= 500 é falso e 200 >= 200 é verdadeiro. A taxa é 10.','if compra >= 500:\n    taxa = 15\nelif compra >= 200:\n    taxa = 10\nelif compra >= 100:\n    taxa = 5\nelse:\n    taxa = 0'),
  q('Com a mesma cadeia, qual é a taxa para compra = 99?','0',['5','10'],'99 falha em >= 500, >= 200 e >= 100. Então o else define taxa = 0.','if compra >= 500:\n    taxa = 15\nelif compra >= 200:\n    taxa = 10\nelif compra >= 100:\n    taxa = 5\nelse:\n    taxa = 0'),
  q('Com a ordem invertida abaixo, qual é a taxa para compra = 600?','5',['15','0'],'600 >= 100 é verdadeiro no primeiro teste, então o bloco roda e os demais são ignorados. O defeito é a ordem.','if compra >= 100:\n    taxa = 5\nelif compra >= 200:\n    taxa = 10\nelif compra >= 500:\n    taxa = 15\nelse:\n    taxa = 0'),
  p('Associe cada compra à taxa correta da cadeia original.',[['compra = 50','0'],['compra = 100','5'],['compra = 250','10'],['compra = 500','15']],'50 não atinge 100. 100 atinge só a menor faixa. 250 passa de 200 mas não de 500. 500 atinge o topo, e a igualdade conta.'),
  o('Ordene o rastreamento da cadeia original para compra = 250.',['Testar compra >= 500: falso','Testar compra >= 200: verdadeiro','Atribuir taxa = 10','Ignorar os testes restantes e continuar após o bloco'],'Os testes seguem de cima para baixo até o primeiro verdadeiro. Depois a cadeia termina.'),
  q('Por que, depois de um elif verdadeiro, os testes seguintes não são avaliados?','A cadeia executa no máximo um bloco: o do primeiro teste verdadeiro',['Porque Python ignora condições com números grandes','Porque os testes restantes são sempre falsos'],'Mesmo que os testes seguintes fossem verdadeiros, como compra >= 100 para 600, eles não rodam.'),
  t('Na cadeia original, quantos testes de condição são avaliados para compra = 150?',['3','três'],'150 >= 500 é falso, 150 >= 200 é falso e 150 >= 100 é verdadeiro. São três testes e o else não é consultado.'),
  g('Complete o limite do último elif para que compras de 100 recebam 5%.','100','A faixa de 5% começa em 100, então o teste é compra >= 100.','if compra >= 500:\n    taxa = 15\nelif compra >= 200:\n    taxa = 10\nelif compra >= ____:\n    taxa = 5\nelse:\n    taxa = 0')
  ]},
  {id:'py-lg-5-4-frete-if-elif-else',title:'Projete a decisão do frete',subtitle:'Aplicação · validar, priorizar e classificar',theory:'Uma transportadora calcula o frete de pacotes com peso de 0 a 30 kg, exclusive 0 e inclusive 30, e uma marcação de urgência. Pesos fora dessa faixa são inválidos. Pacotes urgentes pagam 40, os comuns de até 5 kg pagam 15 e os demais pagam 25. A ordem da cadeia precisa refletir essas prioridades: validar primeiro, tratar o caso especial em seguida e deixar o else para o restante. Uma condição composta como peso <= 0 or peso > 30 concentra toda a entrada inválida em um único teste.',questions:[
  q('Com peso = 5 e urgente = False, qual é o frete?','15',['25','40'],'Peso 5 é válido. Como não é urgente, o teste peso <= 5 é verdadeiro, então o frete é 15.','if peso <= 0 or peso > 30:\n    print("peso inválido")\nelif urgente:\n    frete = 40\nelif peso <= 5:\n    frete = 15\nelse:\n    frete = 25'),
  t('Com peso = 12 e urgente = True, qual é o frete?','40','12 é um peso válido. O pacote é urgente, e o frete é 40 sem comparar o peso de novo.','if peso <= 0 or peso > 30:\n    print("peso inválido")\nelif urgente:\n    frete = 40\nelif peso <= 5:\n    frete = 15\nelse:\n    frete = 25'),
  q('Com peso = 0 e urgente = True, o que o código faz?','Mostra peso inválido, sem calcular frete',['Define frete = 40','Define frete = 15'],'0 <= 0 é verdadeiro no primeiro teste. A urgência nem é consultada.','if peso <= 0 or peso > 30:\n    print("peso inválido")\nelif urgente:\n    frete = 40\nelif peso <= 5:\n    frete = 15\nelse:\n    frete = 25'),
  t('Com peso = 30 e urgente = False, qual é o frete?','25','30 > 30 é falso, então o peso é válido. Como não é urgente e 30 <= 5 é falso, cai no else: 25.','if peso <= 0 or peso > 30:\n    print("peso inválido")\nelif urgente:\n    frete = 40\nelif peso <= 5:\n    frete = 15\nelse:\n    frete = 25'),
  p('Associe cada pacote ao resultado da cadeia.',[['2 kg, comum','15'],['5.5 kg, comum','25'],['8 kg, urgente','40'],['-1 kg, comum','Peso inválido']],'2 kg passa em peso <= 5. 5.5 kg falha nesse teste e cai no else. A urgência vence o peso e valores negativos são rejeitados antes de tudo.'),
  o('Ordene as camadas da decisão do frete, da primeira a testar à última.',['Rejeitar pesos fora de 0 a 30','Tratar os pacotes urgentes','Separar os comuns de até 5 kg','Deixar o else para os demais comuns'],'Primeiro a validação, depois o caso especial, depois a classificação por peso, e o else cobre o que sobrou.'),
  q('Por que o teste de peso inválido vem antes do teste de urgência?','Para que um pacote urgente de 50 kg não receba frete de 40',['Porque or sempre precisa ser o primeiro teste','Porque urgente só pode ser testado uma vez'],'Se a urgência viesse antes, ela atenderia pacotes de peso impossível. A validação deve proteger todo o restante.'),
  g('Complete o limite de peso dos pacotes comuns leves, que incluem 5 kg.','5','Para pagar 15 com exatamente 5 kg, o teste é peso <= 5.','elif urgente:\n    frete = 40\nelif peso <= ____:\n    frete = 15\nelse:\n    frete = 25')
  ]},
  {id:'py-lg-5-5-revisao-condicoes',title:'Depure condições compostas',subtitle:'Desafio de revisão · precedência e ordem',theory:'Uma piscina libera a entrada para sócios ou convidados, desde que a pessoa não esteja suspensa. Em Python, not é avaliado antes de and, e and antes de or, então socio or convidado and not suspenso significa socio or (convidado and not suspenso). Esse tipo de erro roda sem aviso e libera quem não deveria. Os defeitos mais comuns em condições compostas são and no lugar de or, comparação sem o limite, cadeia de elif em ordem errada e else que aceita valores impossíveis. Depurar é calcular o ramo esperado à mão e comparar com o ramo executado.',questions:[
  q('Com socio = True, convidado = False e suspenso = True, qual é o resultado?','True, e o sócio suspenso entra indevidamente',['False, e o sócio suspenso é barrado','Erro de sintaxe'],'Pela precedência: convidado and not suspenso = False and False = False. Depois socio or False = True. O defeito está na falta de parênteses.','socio or convidado and not suspenso'),
  q('Qual escrita barra o sócio suspenso e libera sócio ou convidado que não estejam suspensos?','(socio or convidado) and not suspenso',['socio and convidado and not suspenso','socio or convidado or not suspenso'],'Os parênteses agrupam quem tem direito de entrar, e o and not suspenso se aplica a todos. As outras escritas exigem as duas condições ou deixam suspensos entrarem.'),
  t('Com socio = False, convidado = True e suspenso = False, qual é o valor de (socio or convidado) and not suspenso?',['True','true','verdadeiro','Verdadeiro'],'(False or True) = True e not False = True, então True and True = True.'),
  p('Associe cada defeito ao sintoma esperado.',[['and no lugar de or numa faixa','Quase nenhum valor satisfaz a condição'],['> no lugar de >=','O valor do limite cai no ramo errado'],['Teste geral antes do específico num elif','O ramo específico nunca executa'],['else sem validar a entrada','Valores impossíveis caem no último ramo']],'Cada defeito deixa um sintoma que um teste bem escolhido revela.'),
  q('Com nota = 9, qual saída este código mostra?','Recuperação',['Aprovado','Reprovado'],'9 >= 5 é verdadeiro no primeiro teste, então o elif com 7 nunca é avaliado. A ordem está invertida.','if nota >= 5:\n    print("Recuperação")\nelif nota >= 7:\n    print("Aprovado")\nelse:\n    print("Reprovado")'),
  t('No mesmo código, quantas notas inteiras de 0 a 10 chegam ao ramo Aprovado?',['0','zero','nenhuma'],'Toda nota que passa em nota >= 7 já passou em nota >= 5, e esse teste vem antes. O ramo Aprovado fica inalcançável.','if nota >= 5:\n    print("Recuperação")\nelif nota >= 7:\n    print("Aprovado")\nelse:\n    print("Reprovado")'),
  o('Ordene o diagnóstico de uma condição composta suspeita.',['Escolher entradas nos limites de cada faixa','Calcular à mão o ramo esperado para cada entrada','Executar e comparar com o esperado','Reordenar ou corrigir a condição divergente','Repetir todos os casos, não só o que falhou'],'Os limites expõem erros de comparação. Depois da correção, todos os casos voltam a ser testados porque a mudança pode afetar os demais.'),
  g('Complete a regra corrigida de acesso.','and','A regra libera sócio ou convidado, e a pessoa ainda precisa não estar suspensa. O operador que une os dois grupos é and.','if (socio or convidado) ____ not suspenso:\n    print("Pode entrar")')
  ]}
  ];
})();
